+// Sales from the till. Each dish sold uses one portion of its recipe per
+// unit of `qty`; the ingredients are consumed with ref `sale:<ticket>`.
+// A ticket is imported once; importing is all or nothing.
+import { AppError } from "../errors.js";
+import { dayOf } from "../dates.js";
+import { consume } from "./batches.js";
+import { getItem, onHand } from "./items.js";
+import { getDish } from "./menu.js";
+import { getRecipe, scaled } from "./recipes.js";
+
+const round3 = (n) => Math.round(n * 1000) / 1000;
+
+/** True when a ticket has already been imported. */
+export function isImported(store, ticket) {
+  return (store.data.sales ?? []).some((s) => s.ticket === ticket);
+}
+
+/**
+ * Records sale lines [{ row, ticket, soldAt, dishId, qty }] and consumes their
+ * ingredients. Tickets already imported are skipped. Throws (changing nothing)
+ * when an item runs out, naming the row. Returns { tickets, dishes } imported.
+ */
+export function recordSales(store, lines) {
+  const fresh = lines.filter((l) => !isImported(store, l.ticket));
+  const planned = fresh.map((l) => {
+    const dish = getDish(store, l.dishId);
+    const uses = scaled(getRecipe(store, dish.recipeId), l.qty).filter((u) => u.qty > 0);
+    return { ...l, uses };
+  });
+
+  // Check the whole file first, so the error names the row that runs out.
+  const left = new Map();
+  for (const p of planned) {
+    for (const u of p.uses) {
+      const item = getItem(store, u.itemId);
+      const before = left.has(u.itemId) ? left.get(u.itemId) : round3(onHand(store, u.itemId));
+      if (before < u.qty)
+        throw new AppError("sale_out_of_stock", { row: p.row, item: item.name, available: before, unit: item.unit });
+      left.set(u.itemId, round3(before - u.qty));
+    }
+  }
+
+  const backup = structuredClone(store.data);
+  try {
+    store.data.sales ??= [];
+    for (const p of planned) {
+      for (const u of p.uses) consume(store, u.itemId, u.qty, { at: p.soldAt, ref: `sale:${p.ticket}` });
+      store.data.sales.push({ id: store.nextId("sale"), ticket: p.ticket, soldAt: p.soldAt, dishId: p.dishId, qty: p.qty, uses: p.uses });
+    }
+  } catch (e) {
+    store.data = backup;
+    throw e;
+  }
+  return { tickets: new Set(planned.map((p) => p.ticket)).size, dishes: planned.reduce((s, p) => s + p.qty, 0) };
+}
+
+/**
+ * Variance per item between two days (inclusive): theoretical use from sales,
+ * actual use from `consume` movements, and the difference (actual - theoretical).
+ */
+export function varianceReport(store, from, to) {
+  const inRange = (day) => day >= from && day <= to;
+  const theoretical = new Map();
+  for (const s of store.data.sales ?? []) {
+    if (!inRange(dayOf(s.soldAt))) continue;
+    for (const u of s.uses) theoretical.set(u.itemId, (theoretical.get(u.itemId) ?? 0) + u.qty);
+  }
+  const actual = new Map();
+  for (const m of store.data.movements) {
+    if (m.type !== "consume" || !inRange(dayOf(m.at))) continue;
+    const batch = store.data.batches.find((b) => b.id === m.batchId);
+    if (!batch) continue;
+    actual.set(batch.itemId, (actual.get(batch.itemId) ?? 0) + m.qty);
+  }
+  const ids = [...new Set([...theoretical.keys(), ...actual.keys()])].sort((a, b) => a - b);
+  return ids
+    .map((itemId) => {
+      const t = round3(theoretical.get(itemId) ?? 0);
+      const a = round3(actual.get(itemId) ?? 0);
+      const item = store.data.items.find((i) => i.id === itemId);
+      return { itemId, name: item?.name ?? null, unit: item?.unit ?? null, theoretical: t, actual: a, difference: round3(a - t) };
+    })
+    .filter((l) => l.theoretical > 0 || l.actual > 0);
+}
